let idioma = localStorage.getItem("sitio-idioma-preferido") || IDIOMA_INICIAL;

function t() { return I18N[idioma]; }
function d() { return DATOS[idioma]; }

function escapeHtml(s) {
  return s.replace(/[&<>"']/g, (m) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[m]));
}

function pintarPerfil() {
  const dp = d();
  document.getElementById("mHeading").textContent = dp.nombre_completo;
  document.getElementById("mSub").textContent = dp.titulo_profesional;
  document.getElementById("pKicker").textContent = t().kicker;
  document.getElementById("pNombre").textContent = dp.nombre_completo;
  document.getElementById("pTitulo").textContent = dp.titulo_profesional;
  document.getElementById("pResumen").textContent = dp.resumen_profesional;

  const contacto = document.getElementById("pContacto");
  const partes = [dp.ciudad, dp.email, dp.telefono_formato];
  contacto.innerHTML = partes.filter(Boolean).map(escapeHtml).join(" &middot; ") +
    (dp.linkedin ? ` &middot; <a href="${dp.linkedin}" target="_blank" rel="noopener">LinkedIn</a>` : "");

  document.getElementById("hExperiencia").textContent = t().hExperiencia;
  document.getElementById("hTecnologias").textContent = t().hTecnologias;
  document.getElementById("hCursos").textContent = t().hCursos;
  document.getElementById("navPerfil").textContent = t().navPerfil;
  document.getElementById("navExperiencia").textContent = t().navExperiencia;
  document.getElementById("navTecnologias").textContent = t().navTecnologias;
  document.getElementById("navCursos").textContent = t().navCursos;
  const listaCursos = document.getElementById("listaCursosDestacados");
  listaCursos.innerHTML = (dp.cursos_destacados || []).map(c => `
    <li>
      <a href="${c.url}" target="_blank" rel="noopener">${escapeHtml(c.nombre)}</a>
      <span class="curso-institucion">${escapeHtml(c.institucion)}</span>
    </li>
  `).join("");
  document.getElementById("ctaCursos").textContent = t().ctaCursos;
  document.getElementById("ctaCursos").href = dp.catalogo_cursos;
  document.getElementById("ctaDescargarCV").textContent = t().ctaDescargarCV;
  document.getElementById("ctaDescargarCV").href = t().cvArchivo;
}

function agruparPorEmpresa(empleos) {
  const grupos = [];
  for (const emp of empleos) {
    const ultimo = grupos[grupos.length - 1];
    if (ultimo && ultimo.empresa === emp.empresa) {
      ultimo.puestos.push(emp);
    } else {
      grupos.push({ empresa: emp.empresa, puestos: [emp] });
    }
  }
  return grupos;
}

function pintarExperiencia() {
  const grupos = agruparPorEmpresa(d().empleos);
  const cont = document.getElementById("listaExperiencia");
  cont.innerHTML = "";

  for (const g of grupos) {
    const div = document.createElement("div");
    div.className = "empresa-grupo";
    const puestosHtml = g.puestos.map(p => `
      <div class="puesto-item">
        <div class="puesto-cabeza">
          <span class="puesto-nombre">${escapeHtml(p.puesto)}</span>
          <span class="puesto-periodo">${escapeHtml(p.periodo)} (${escapeHtml(p.duracion)})</span>
        </div>
        ${p.ubicacion ? `<div class="puesto-lugar">${escapeHtml(p.ubicacion)}</div>` : ""}
        <ul class="puesto-actividades">
          ${p.actividades.map(a => `<li>${escapeHtml(a)}</li>`).join("")}
        </ul>
        <div class="tool-row">
          ${p.herramientas.map(h => `<span class="tool-chip">${escapeHtml(h)}</span>`).join("")}
        </div>
      </div>
    `).join("");

    div.innerHTML = `<div class="empresa-nombre">${escapeHtml(g.empresa)}</div>${puestosHtml}`;
    cont.appendChild(div);
  }
}

function tarjetaTech(item) {
  return `
    <div class="tech-card">
      <div class="tech-icon ${item.badge ? "on-badge" : ""}">${ICONOS[item.key] || ""}</div>
      <div class="tech-label">${escapeHtml(item.label)}</div>
    </div>
  `;
}

function pintarTecnologias() {
  const grid = document.getElementById("gridTecnologias");
  grid.innerHTML = TECH_PRIMARIA.filter(it => it.visible).map(tarjetaTech).join("");

  const cont = document.getElementById("contenidoSecundaria");
  cont.innerHTML = `<div class="tech-grid secundaria">${TECH_SECUNDARIA.filter(it => it.visible).map(tarjetaTech).join("")}</div>`;

  document.getElementById("resumenSecundaria").textContent = t().verMasTecnologias;
}

function reflejarBotonIdioma() {
  document.getElementById("langEs").classList.toggle("active", idioma === "es");
  document.getElementById("langEn").classList.toggle("active", idioma === "en");
  document.documentElement.lang = idioma;
}

function pintarTodo() {
  pintarPerfil();
  pintarExperiencia();
}

function cambiarIdioma(nuevo) {
  if (idioma === nuevo) return;
  idioma = nuevo;
  localStorage.setItem("sitio-idioma-preferido", idioma);
  reflejarBotonIdioma();
  pintarTodo();
}

document.getElementById("langEs").addEventListener("click", () => cambiarIdioma("es"));
document.getElementById("langEn").addEventListener("click", () => cambiarIdioma("en"));

const THEME_KEY = "sitio-tema-preferido";
const themeToggle = document.getElementById("themeToggle");
function aplicarTema(tema) {
  document.documentElement.setAttribute("data-theme", tema);
  themeToggle.textContent = tema === "dark" ? "☀️" : "🌙";
  themeToggle.setAttribute("aria-label", tema === "dark" ? t().themeDark : t().themeLight);
}
let temaActual = localStorage.getItem(THEME_KEY) || TEMA_INICIAL;
aplicarTema(temaActual);
themeToggle.addEventListener("click", () => {
  temaActual = temaActual === "dark" ? "light" : "dark";
  localStorage.setItem(THEME_KEY, temaActual);
  aplicarTema(temaActual);
});

reflejarBotonIdioma();
pintarTodo();
pintarTecnologias();
